"""Seed DEMO data (clearly flagged is_demo=true) so the dashboards are populated before real customers exist.

    cd backend && python -m scripts.seed_demo [--days 42] [--reset]

* Service/counter configuration is created if missing (it is configuration, not data).
* Everything customer-shaped (users, tokens, events, records, predictions, forecasts) is generated by the
  discrete-event simulator and flagged `is_demo = true`. `--reset` deletes only flagged rows.
* Demo accounts (password from DEMO_PASSWORD, default shown below):
    admin@queueless.demo, staff1..4@queueless.demo, customer1@queueless.demo ...
"""
import argparse
import os
import random
import sys
from datetime import datetime, timedelta, timezone
from pathlib import Path

import numpy as np

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from sqlalchemy import delete, select  # noqa: E402

from app.db import Base, SessionLocal, engine  # noqa: E402
from app.engine import queue_engine as qe  # noqa: E402
from app.ml import predictor  # noqa: E402
from app.ml.features import DEMAND_BIN_MINUTES, WAIT_FEATURES, demand_feature_row, fallback_wait_minutes  # noqa: E402
from app.ml.simulation import COUNTERS, SERVICES, SimConfig, simulate  # noqa: E402
from app.models import (  # noqa: E402
    Counter, CounterService, CounterStatus, DemandForecast, Notification, Prediction, Priority, QueueEvent, QueueToken, Role, Service,
    ServiceRecord, SpecialEvent, Staff, TokenStatus, User, utcnow,
)
from app.realtime import Outbox  # noqa: E402
from app.security import hash_password  # noqa: E402
from app.services import settings_service as cfg  # noqa: E402

DEMO_PASSWORD = os.environ.get("DEMO_PASSWORD", "Demo@12345")
BINS_PER_DAY = 48


def to_utc(naive_local: datetime, tz) -> datetime:
    return naive_local.replace(tzinfo=tz).astimezone(timezone.utc)


def reset_demo(db) -> None:
    ids = list(db.scalars(select(QueueToken.token_id).where(QueueToken.is_demo.is_(True))))
    for i in range(0, len(ids), 500):
        chunk = ids[i:i + 500]
        for model in (Prediction, ServiceRecord, QueueEvent, Notification):
            db.execute(delete(model).where(model.token_id.in_(chunk)))
        db.execute(delete(QueueToken).where(QueueToken.token_id.in_(chunk)))
    db.execute(delete(DemandForecast))   # forecasts are derived data, rebuilt below
    demo_users = list(db.scalars(select(User.user_id).where(User.is_demo.is_(True))))
    if demo_users:
        db.execute(Counter.__table__.update().where(
            Counter.assigned_staff_id.in_(select(Staff.staff_id).where(Staff.user_id.in_(demo_users)))).values(assigned_staff_id=None))
        db.execute(delete(Staff).where(Staff.user_id.in_(demo_users)))
        db.execute(delete(Notification).where(Notification.user_id.in_(demo_users)))
        db.execute(delete(User).where(User.user_id.in_(demo_users)))
    db.commit()
    qe.clear_caches()


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--days", type=int, default=42)
    ap.add_argument("--reset", action="store_true")
    ap.add_argument("--seed", type=int, default=2026)
    args = ap.parse_args()
    rng = random.Random(args.seed)

    from app import models  # noqa: F401
    if engine.dialect.name == "sqlite":
        Base.metadata.create_all(engine)

    with SessionLocal() as db:
        if args.reset:
            reset_demo(db)
        elif db.scalar(select(QueueToken.token_id).where(QueueToken.is_demo.is_(True)).limit(1)):
            sys.exit("Demo data already present. Re-run with --reset to replace it.")

        loc = cfg.get_location(db)
        tz = cfg.local_tz(loc)
        today = cfg.local_today(loc)

        # ---- configuration (services, counters)
        svc_map: dict[int, int] = {}
        for s in SERVICES:
            row = db.scalar(select(Service).where(Service.location_id == loc.location_id, Service.code == s["code"]))
            if not row:
                row = Service(location_id=loc.location_id, service_name=s["name"], code=s["code"], description=s["description"],
                              average_service_duration=s["mean"])
                db.add(row); db.flush()
            svc_map[s["service_id"]] = row.service_id
        pw_hash = hash_password(DEMO_PASSWORD)
        admin = db.scalar(select(User).where(User.email == "admin@queueless.demo"))
        if not admin:
            db.add(User(name="Demo Admin", email="admin@queueless.demo", password_hash=pw_hash, role=Role.admin, is_demo=True))
        staff_rows = []
        for i, nm in enumerate(["Aarav Mehta", "Diya Nair", "Kabir Rao", "Isha Verma"], start=1):
            u = db.scalar(select(User).where(User.email == f"staff{i}@queueless.demo"))
            if not u:
                u = User(name=nm, email=f"staff{i}@queueless.demo", password_hash=pw_hash, role=Role.staff, is_demo=True)
                db.add(u); db.flush()
            st = db.scalar(select(Staff).where(Staff.user_id == u.user_id)) or Staff(user_id=u.user_id)
            st.location_id = loc.location_id
            db.add(st); db.flush(); staff_rows.append(st)
        cmap: dict[int, int] = {}
        for cid, name, svcs in COUNTERS:
            c = db.scalar(select(Counter).where(Counter.location_id == loc.location_id, Counter.counter_name == name))
            if not c:
                c = Counter(location_id=loc.location_id, counter_name=name, status=CounterStatus.open if cid <= 4 else CounterStatus.closed,
                            assigned_staff_id=staff_rows[cid - 1].staff_id if cid <= 4 else None)
                db.add(c); db.flush()
                db.add_all([CounterService(counter_id=c.counter_id, service_id=svc_map[s]) for s in svcs])
            cmap[cid] = c.counter_id
        db.commit()

        # ---- simulate history (ends yesterday)
        cfg_sim = SimConfig(days=args.days, start_date=today - timedelta(days=args.days), seed=args.seed)
        sim = simulate(cfg_sim)
        df = sim.tokens
        print(f"simulated {len(df):,} demo tokens over {args.days} days")
        for d in sim.event_dates:
            if not db.get(SpecialEvent, (d, loc.location_id)):
                db.add(SpecialEvent(event_date=d, location_id=loc.location_id, label="Demo special event", is_holiday=False))
        for d in sim.holiday_dates:
            if not db.get(SpecialEvent, (d, loc.location_id)):
                db.add(SpecialEvent(event_date=d, location_id=loc.location_id, label="Holiday", is_holiday=True))

        users = []
        for n in range(1, 131):
            email = f"customer{n}@queueless.demo"
            u = db.scalar(select(User).where(User.email == email)) or User(name=f"Demo Customer {n}", email=email, password_hash=pw_hash,
                                                                           role=Role.customer, is_demo=True)
            db.add(u); users.append(u)
        db.flush()
        user_ids = [u.user_id for u in users]

        # ---- batch predictions for history (out-of-sample for the trained model)
        feats = df[WAIT_FEATURES].to_dict("records")
        for f in feats:
            f["service_type"] = svc_map[int(f["service_type"])]
        ml_preds = predictor.predict_wait_batch(feats) if predictor.wait_model_info() else None

        tokens, meta = [], []
        for i, r in enumerate(df.itertuples(index=False)):
            status = {"served": TokenStatus.completed, "cancelled": TokenStatus.cancelled, "no_show": TokenStatus.no_show}[r.outcome]
            entered = to_utc(r.entered_at.to_pydatetime(), tz)
            t = QueueToken(user_id=rng.choice(user_ids), service_id=svc_map[r.service_id], counter_id=cmap.get(r.counter_id) if r.counter_id == r.counter_id else None,
                           queue_date=r.date, token_number=int(r.token_number), token_label=f"{next(s['code'] for s in SERVICES if s['service_id'] == r.service_id)}-{int(r.token_number):03d}",
                           priority_type=Priority(r.priority), status=status, is_demo=True, created_at=entered,
                           arrival_time=entered + timedelta(minutes=2) if status != TokenStatus.cancelled else None)
            tokens.append(t); meta.append((r, entered, i))
        for i in range(0, len(tokens), 1000):
            db.add_all(tokens[i:i + 1000]); db.flush()
            print(f"  tokens {min(i + 1000, len(tokens)):,}/{len(tokens):,}", end="\r")
        print()

        events, records, preds = [], [], []
        for t, (r, entered, i) in zip(tokens, meta):
            events.append(QueueEvent(token_id=t.token_id, event_type="token_created", timestamp=entered, metadata_={"priority": r.priority}))
            if r.outcome == "cancelled":
                events.append(QueueEvent(token_id=t.token_id, event_type="cancelled", timestamp=to_utc(r.cancel_at.to_pydatetime(), tz), metadata_={"by": "customer"}))
                continue
            called = to_utc(r.called_at.to_pydatetime(), tz)
            events.append(QueueEvent(token_id=t.token_id, event_type="called", timestamp=called, metadata_={"counter_id": t.counter_id}))
            if r.outcome == "no_show":
                events.append(QueueEvent(token_id=t.token_id, event_type="no_show", timestamp=called + timedelta(minutes=2), metadata_={}))
                continue
            start, end = to_utc(r.service_start.to_pydatetime(), tz), to_utc(r.service_end.to_pydatetime(), tz)
            events += [QueueEvent(token_id=t.token_id, event_type="service_started", timestamp=start, metadata_={}),
                       QueueEvent(token_id=t.token_id, event_type="service_completed", timestamp=end, metadata_={})]
            records.append(ServiceRecord(token_id=t.token_id, counter_id=t.counter_id, service_start_time=start, service_end_time=end,
                                         actual_service_duration=round(r.service_minutes, 2), actual_wait_minutes=round(r.actual_wait_minutes, 2),
                                         rating=rng.choice([3, 4, 4, 5, 5]) if rng.random() < 0.4 else None))
            f = feats[i]
            if ml_preds:
                p = ml_preds[i]
                preds.append(Prediction(token_id=t.token_id, predicted_waiting_time=p.minutes, prediction_lower_bound=p.lower, prediction_upper_bound=p.upper,
                                        method="ml", model_version=p.model_version, features=f, prediction_timestamp=entered))
            else:
                fb = fallback_wait_minutes(f)
                if fb is not None:
                    preds.append(Prediction(token_id=t.token_id, predicted_waiting_time=fb, method="fallback", model_version="fallback-v1",
                                            features=f, prediction_timestamp=entered))
        for batch in (events, records, preds):
            for i in range(0, len(batch), 2000):
                db.add_all(batch[i:i + 2000]); db.flush()
        print(f"  {len(events):,} events, {len(records):,} service records, {len(preds):,} predictions")

        # ---- demand forecasts (horizon 60) for the last 14 days, scored against actual arrivals
        n_bins = (args.days + 1) * BINS_PER_DAY
        base_day = cfg_sim.start_date
        forecasts = []
        holidays, events_set = set(sim.holiday_dates), set(sim.event_dates)
        for s in SERVICES:
            sid = s["service_id"]
            counts = np.zeros(n_bins, dtype=int)
            d = df[df["service_id"] == sid]
            idx = ((d["entered_at"].dt.normalize() - np.datetime64(base_day)).dt.days * BINS_PER_DAY
                   + (d["entered_at"].dt.hour * 60 + d["entered_at"].dt.minute) // DEMAND_BIN_MINUTES)
            np.add.at(counts, idx.to_numpy(), 1)
            get = lambda i, c=counts: int(c[i]) if 0 <= i < len(c) else 0
            for day in range(max(0, args.days - 14), args.days):
                dt = base_day + timedelta(days=day)
                if dt.weekday() == 6:
                    continue
                for hour in range(9, 17):
                    i = day * BINS_PER_DAY + hour * 2
                    f = demand_feature_row(get_count=get, bin_index=i, horizon_bins=2, hour_of_day=float(hour), day_of_week=dt.weekday(),
                                           is_holiday=int(dt in holidays), special_event=int(dt in events_set), service_type=svc_map[sid])
                    ml = predictor.predict_demand(60, f)
                    pred, ver, method = (ml[0], ml[1], "ml") if ml else (f["historical_demand"], "historical-mean-v1", "fallback")
                    forecasts.append(DemandForecast(service_id=svc_map[sid], interval_start=to_utc(datetime(dt.year, dt.month, dt.day, hour), tz),
                                                    horizon_minutes=60, predicted_arrivals=round(pred, 2), actual_arrivals=get(i) + get(i + 1),
                                                    method=method, model_version=ver))
        db.add_all(forecasts); db.flush()

        # ---- live "today" snapshot so the dashboards have something moving
        now = utcnow()
        counters_db = {c.counter_id: c for c in db.scalars(select(Counter))}
        live_users = iter(rng.sample(user_ids, 60))
        numbers = {sid: (db.scalar(select(QueueToken.token_number).where(QueueToken.service_id == sid, QueueToken.queue_date == today)
                                   .order_by(QueueToken.token_number.desc()).limit(1)) or 0) for sid in svc_map.values()}
        code_of = {svc_map[s["service_id"]]: s["code"] for s in SERVICES}

        def make(service_id, minutes_ago, status, counter=None, priority=Priority.none):
            numbers[service_id] += 1
            t = QueueToken(user_id=next(live_users), service_id=service_id, counter_id=counter, queue_date=today, token_number=numbers[service_id],
                           token_label=f"{code_of[service_id]}-{numbers[service_id]:03d}", priority_type=priority, status=status, is_demo=True,
                           created_at=now - timedelta(minutes=minutes_ago), arrival_time=now - timedelta(minutes=minutes_ago - 1) if rng.random() < 0.5 else None)
            db.add(t); db.flush()
            db.add(QueueEvent(token_id=t.token_id, event_type="token_created", timestamp=t.created_at, metadata_={}))
            return t

        done = 0
        for k in range(14):                                   # completed earlier today
            sid = rng.choice(list(svc_map.values()))
            cid = rng.choice([cmap[1], cmap[2], cmap[3], cmap[4]])
            if sid not in counters_db[cid].service_ids:
                continue
            t = make(sid, rng.randint(60, 200), TokenStatus.completed, cid)
            dur = max(2.0, rng.gauss(8, 3)); wait = max(0.0, rng.gauss(9, 5))
            start = t.created_at + timedelta(minutes=wait)
            db.add(ServiceRecord(token_id=t.token_id, counter_id=cid, service_start_time=start, service_end_time=start + timedelta(minutes=dur),
                                 actual_service_duration=round(dur, 2), actual_wait_minutes=round(wait, 2)))
            done += 1
        serving = [(cmap[1], list(svc_map.values())[0]), (cmap[2], list(svc_map.values())[1])]
        for cid, sid in serving:
            t = make(sid, 22, TokenStatus.serving, cid)
            db.add(ServiceRecord(token_id=t.token_id, counter_id=cid, service_start_time=now - timedelta(minutes=3)))
        make(list(svc_map.values())[2], 18, TokenStatus.called, cmap[4])
        for k in range(15):
            sid = rng.choices(list(svc_map.values()), weights=[3, 3, 2.5, 1.5])[0]
            make(sid, rng.randint(1, 40), TokenStatus.booked if rng.random() < 0.6 else TokenStatus.waiting,
                 priority=Priority.senior if rng.random() < 0.1 else Priority.none)
        db.flush()
        qe.clear_caches()
        qe.refresh(db, Outbox())
        db.commit()
        print(f"demo data ready. Log in as admin@queueless.demo / customer1@queueless.demo (password: DEMO_PASSWORD, default '{DEMO_PASSWORD}').")


if __name__ == "__main__":
    main()
